import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface ServiceInfraArgs {
    /** Optional: Provide an existing VPC ID. If omitted, a managed VPC is created. */
    vpcId?: pulumi.Input<string>;
    /** Optional: Provide existing private subnet IDs. If omitted, managed subnets are created. */
    privateSubnetIds?: pulumi.Input<string>[];
}

export class ServiceInfrastructure extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.Bucket;
    public readonly database: aws.rds.Instance;
    public readonly serviceRole: aws.iam.Role;
    public readonly dbEndpoint: pulumi.Output<string>;

    constructor(name: string, args: ServiceInfraArgs = {}, opts?: pulumi.ComponentResourceOptions) {
        super("myinfra:ServiceInfrastructure", name, {}, opts);

        const config = new pulumi.Config();
        // Idiom: Prefer explicit config, fallback to stack name (e.g., dev/prod)
        const environment = config.get("environment") || pulumi.getStack();
        const isProd = environment === "prod";

        // ─────────────────────────────────────────────────────────────────────
        // 1. S3 Bucket (Versioning + Encryption + No Public Access)
        // ─────────────────────────────────────────────────────────────────────
        this.bucket = new aws.s3.Bucket(`${name}-assets`, {
            versioning: { enabled: true },
            serverSideEncryptionConfiguration: {
                rule: {
                    applyServerSideEncryptionByDefault: {
                        // AES-256 meets spec; switch to "aws:kms" if KMS-managed key preferred
                        sseAlgorithm: isProd ? "aws:kms" : "AES256",
                    },
                },
            },
            tags: { Environment: environment, ManagedBy: "pulumi" },
        }, { parent: this });

        // Enforce acceptance criterion: No public access
        new aws.s3.BucketPublicAccessBlock(`${name}-bucket-protect`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        // ─────────────────────────────────────────────────────────────────────
        // 2. IAM Role & Policy (Least Privilege, Prod ≠ Wildcards)
        // ─────────────────────────────────────────────────────────────────────
        const trustPolicy = {
            Version: "2012-10-17",
            Statement: [{
                Effect: "Allow",
                Principal: {
                    // Dev: EC2 programmatic access | Prod: EKS OIDC trust
                    Service: isProd ? "pods.oidc.amazonaws.com" : "ec2.amazonaws.com",
                },
                Action: "sts:AssumeRole",
                Condition: isProd ? {
                    StringEquals: { "pods.oidc.amazonaws.com/aud": "sts.amazonaws.com" },
                } : {},
            }],
        };

        this.serviceRole = new aws.iam.Role(`${name}-svc-role`, {
            assumeRolePolicy: JSON.stringify(trustPolicy),
            tags: { Environment: environment, ManagedBy: "pulumi" },
        }, { parent: this });

        // Construct resource ARNs for strict least-privilege
        const s3BucketArn = this.bucket.arn;
        const s3ObjectsArn = s3BucketArn.apply(arn => `${arn}/*`);
        const rdsArn = this.database.id.apply(id => 
            `arn:aws:rds:${pulumi.getRegion()}:${pulumi.getProject()}:${id}`
        );

        const policyStatements = isProd
            ? [
                  {
                      Effect: "Allow",
                      Action: ["s3:GetObject", "s3:PutObject", "s3:ListBucket"],
                      Resource: [s3BucketArn, s3ObjectsArn],
                  },
                  {
                      Effect: "Allow",
                      Action: ["rds-data:ExecuteStatement", "rds-data:BatchExecuteStatement"],
                      Resource: rdsArn,
                  },
                  // Required when using aws:kms encryption
                  { Effect: "Allow", Action: ["kms:Decrypt", "kms:GenerateDataKey"], Resource: "*" },
              ]
            : [
                  {
                      Effect: "Allow",
                      Action: ["s3:*", "rds:*"],
                      Resource: "*",
                  },
              ];

        new aws.iam.RolePolicy(`${name}-svc-policy`, {
            role: this.serviceRole,
            policy: JSON.stringify({ Version: "2012-10-17", Statement: policyStatements }),
        }, { parent: this });

